#include "powder/gpu.hpp"
#include "powder/clump.hpp"
#include <algorithm>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
std::vector<Particle> charge(){std::vector<Particle> v;for(unsigned i=0;i<32;++i){double r=.001+(i%3)*.0001;for(unsigned j=0;j<2;++j){Particle p;p.id=i*2+j+1;p.diameter_m=2*(r+j*.00007);p.material.density_kg_m3=1500+(i%2)*500;p.position_m={i*.01+j*(2*r+.00007-1e-6),0,0};p.velocity_m_s={j?-.001:.001,j?-.01:.01,0};p.angular_velocity_rad_s={0,0,j?1.:-1.};v.push_back(p);}}return v;}
ClumpWorld cpu(const std::vector<Particle>& p,const MaterialContact& m){ClumpWorld w;w.gravity_m_s2={};w.pair_models={{{0,0},m}};w.wall_models={{0,m}};for(const auto& a:p){auto b=make_clump(a.id,0,{{{},a.diameter_m}},a.material.density_kg_m3);b.position_m=a.position_m;b.velocity_m_s=a.velocity_m_s;const double inertia=sphere_properties(a.diameter_m,a.material).inertia_kg_m2;b.angular_momentum_world={inertia*a.angular_velocity_rad_s.x,inertia*a.angular_velocity_rad_s.y,inertia*a.angular_velocity_rad_s.z};w.bodies.push_back(b);}return w;}
double difference(const std::vector<Particle>& p,const ClumpWorld& w){double e=0;for(std::size_t i=0;i<p.size();++i){auto omega=clump_omega(w.bodies[i]);for(double d:{p[i].position_m.x-w.bodies[i].position_m.x,p[i].position_m.y-w.bodies[i].position_m.y,p[i].velocity_m_s.x-w.bodies[i].velocity_m_s.x,p[i].velocity_m_s.y-w.bodies[i].velocity_m_s.y,p[i].angular_velocity_rad_s.z-omega.z})e=std::max(e,std::abs(d));}return e;}
Vec3 momentum(const std::vector<Particle>& p){Vec3 sum;for(const auto& a:p){double m=sphere_properties(a.diameter_m,a.material).mass_kg;sum.x+=m*a.velocity_m_s.x;sum.y+=m*a.velocity_m_s.y;sum.z+=m*a.velocity_m_s.z;}return sum;}
int main(int argc,char** argv){try{
 MaterialContact m;m.law=ContactLaw::Linear;m.linear={1000,.01,250,.0025,.4};auto p=charge();auto w=cpu(p,m);GpuSpheres gpu;gpu.reset(p);gpu.enable_contacts(m,8,128);const double dt=1e-7;double maxerror=0;const auto start=std::chrono::steady_clock::now();gpu.advance_contacts(dt,1,{});w.step(dt);auto pairs=gpu.contact_pairs();check(pairs.size()==32,"contact set size");for(unsigned i=0;i<32;++i)check(pairs[i]==std::make_pair<ParticleId,ParticleId>(i*2+1,i*2+2),"missing/wrong contact");maxerror=difference(gpu.snapshot(),w);
 gpu.advance_contacts(dt,198,{});for(unsigned i=0;i<198;++i)w.step(dt);maxerror=std::max(maxerror,difference(gpu.snapshot(),w));check(maxerror<1e-8,"GPU/CPU friction evolution");
 // Insert/delete an isolated body while preserving all surviving contact histories.
 auto current=gpu.snapshot();Particle distant=current[0];distant.id=999;distant.position_m={2,0,0};distant.velocity_m_s={};distant.angular_velocity_rad_s={};current.push_back(distant);gpu.replace(current);auto with_extra=gpu.snapshot();check(with_extra.size()==65,"insert failed");auto extra=make_clump(distant.id,0,{{{},distant.diameter_m}},distant.material.density_kg_m3);extra.position_m=distant.position_m;w.bodies.push_back(extra);gpu.advance_contacts(dt,1,{});w.step(dt);w.bodies.pop_back();with_extra=gpu.snapshot();with_extra.pop_back();gpu.replace(with_extra);gpu.advance_contacts(dt,100,{});for(unsigned i=0;i<100;++i)w.step(dt);maxerror=std::max(maxerror,difference(gpu.snapshot(),w));check(maxerror<1e-8,"history lost during insertion/deletion");
 gpu.advance_contacts(dt,9700,{});for(unsigned i=0;i<9700;++i)w.step(dt);auto result=gpu.snapshot();maxerror=std::max(maxerror,difference(result,w));check(maxerror<1e-8,"long-run sphere parity");const auto before=momentum(p),after=momentum(result);const double conservation=std::max({std::abs(after.x-before.x),std::abs(after.y-before.y),std::abs(after.z-before.z)});check(conservation<1e-14,"pair momentum conservation");
 // A failed step must not mutate accepted state or drop overflowing contacts.
 std::vector<Particle> dense(3,p[0]);for(unsigned i=0;i<3;++i){dense[i].id=i+1;dense[i].diameter_m=.002;dense[i].position_m={(static_cast<int>(i)-1)*.001999,0,0};dense[i].velocity_m_s={};dense[i].angular_velocity_rad_s={};}gpu.reset(dense);gpu.enable_contacts(m,1,32);bool rejected=false;try{gpu.advance_contacts(dt,2,{});}catch(const std::runtime_error&){rejected=true;}check(rejected&&gpu.physical_time_s()==0,"overflow failed atomicity");auto unchanged=gpu.snapshot();for(unsigned i=0;i<3;++i)check(unchanged[i].position_m.x==dense[i].position_m.x,"overflow committed position");
 gpu.reset(p);gpu.enable_contacts(m,8,128);rejected=false;try{gpu.advance_contacts(1.,1,{});}catch(const std::runtime_error&){rejected=true;}check(rejected&&gpu.physical_time_s()==0,"unsafe dt accepted");gpu.advance_contacts(dt,1,{});check(gpu.physical_time_s()==dt,"recovery after rejected step");
 std::vector<Particle> crowded(4,p[0]);for(unsigned i=0;i<4;++i){crowded[i].id=i+1;crowded[i].diameter_m=.002;crowded[i].position_m={(i%2)*.0021,(i/2)*.0021,0};crowded[i].velocity_m_s={};crowded[i].angular_velocity_rad_s={};}gpu.reset(crowded);gpu.enable_contacts(m,2,2);rejected=false;try{gpu.advance_contacts(dt,1,{});}catch(const std::runtime_error& e){rejected=std::string(e.what()).find("error bits=16")!=std::string::npos;}check(rejected&&gpu.physical_time_s()==0,"candidate overflow was silently dropped");
 gpu.reset(p);auto hertz=m;hertz.law=ContactLaw::HertzMindlin;rejected=false;try{gpu.enable_contacts(hertz);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"unsupported Hertz accepted");
 const double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(argc==2){std::filesystem::path out(argv[1]);check(std::filesystem::create_directory(out),"output must be new");std::ofstream f(out/"result.csv");f<<std::setprecision(17)<<"bodies,steps,dt_s,max_state_error,momentum_error,test_wall_s\n64,10000,"<<dt<<','<<maxerror<<','<<conservation<<','<<elapsed<<'\n';f.close();check(bool(f),"result write");}std::cout<<"GPU contacts passed: error="<<maxerror<<" momentum="<<conservation<<" wall="<<elapsed<<'\n';
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
